['key'=>'terrace-lab','slug'=>'terrace-lab','type'=>'commercial','image'=>9,'fa'=>['title'=>'تراس لب','location'=>'شیراز، فارس','client'=>'Terrace Lab','architect'=>'لیلا فروزان','status'=>'تکمیل‌شده','duration'=>'۹ ماه','budget'=>'سطح سرمایه‌گذاری متوسط','awards'=>'تقدیر ویژه برنامه فرضی «Workscape 2025»','materials'=>'تراکوتا، بتن، چوب راش، پارچه آکوستیک','concept'=>'محیط کار پیرامون تراس‌های سبز کوچک شکل گرفته تا استراحت، جلسه کوتاه و کار فردی همگی به هوای آزاد دسترسی داشته باشند.','challenge'=>'اقلیم گرم شیراز و تابش مستقیم، استفاده از تراس را در بیشتر روزها سخت می‌کرد.','solution'=>'سایه‌بان‌های عمیق، سفال مشبک و جریان هوای متقاطع دمای ادراک‌شده را کاهش دادند.','timeline'=>'تحقیق ۳ هفته • طراحی ۹ هفته • اجرا ۶ ماه','content'=>'تراس لب دفتر یک شرکت پژوهشی است که بین فضاهای خشک آزمایشگاهی و بخش‌های گرم و اجتماعی تعادل برقرار می‌کند.'], 'en'=>['title'=>'Terrace Lab','location'=>'Shiraz, Fars','client'=>'Terrace Lab','architect'=>'Leila Forouzan','status'=>'Completed','duration'=>'9 months','budget'=>'Mid investment range','awards'=>'Special mention — Workscape 2025 (fictional demo recognition)','materials'=>'Terracotta, concrete, beech, acoustic textile','concept'=>'Workspaces gather around planted terraces so breaks, short meetings and individual work can all connect to fresh air.','challenge'=>'Shiraz heat and direct sun made outdoor areas difficult to use for much of the day.','solution'=>'Deep shading, perforated terracotta and cross ventilation reduce perceived temperature.','timeline'=>'Research 3 weeks • Design 9 weeks • Construction 6 months','content'=>'Terrace Lab is a research workplace balancing controlled laboratory zones with warm, social spaces that open to shaded terraces.']],
['key'=>'soft-grid','slug'=>'soft-grid-apartment','type'=>'interior','image'=>10,'fa'=>['title'=>'آپارتمان شبکه نرم','location'=>'الهیه، تهران','client'=>'خصوصی','architect'=>'سارا نیازی','status'=>'تکمیل‌شده','duration'=>'۶ ماه','budget'=>'سطح سرمایه‌گذاری متوسط رو به بالا','awards'=>'—','materials'=>'سنگ لایم‌استون، روکش بلوط دودی، پارچه کتانی، استیل ساتن','concept'=>'شبکه‌ای منظم از کمد، نور و خطوط سقف، زمینه‌ای آرام می‌سازد و مبلمان آزادانه‌تر درون آن قرار می‌گیرد.','challenge'=>'واحد موجود راهروی طولانی و فضاهای پرت زیادی داشت.','solution'=>'دیوارهای غیرسازه‌ای حذف شدند و یک هسته ذخیره‌سازی مرکزی مسیرها را کوتاه کرد.','timeline'=>'طراحی ۶ هفته • ساخت سفارشی ۸ هفته • اجرا ۴ ماه','content'=>'این بازطراحی ۲۶۰ مترمربعی با حذف مرزهای اضافی و ساخت یک هسته چوبی پیوسته، خانه را روشن‌تر و خواناتر کرده است.'], 'en'=>['title'=>'Soft Grid Apartment','location'=>'Elahieh, Tehran','client'=>'Private','architect'=>'Sara Niazi','status'=>'Completed','duration'=>'6 months','budget'=>'Upper-mid investment range','awards'=>'—','materials'=>'Limestone, smoked oak veneer, linen, satin stainless steel','concept'=>'A calm grid of storage, lighting and ceiling lines creates structure while furniture can sit more freely within it.','challenge'=>'The existing apartment had a long corridor and significant leftover space.','solution'=>'Non-structural walls were removed and a central storage core shortened circulation.','timeline'=>'Design 6 weeks • Custom fabrication 8 weeks • Site work 4 months','content'=>'This 260 m² renovation removes unnecessary boundaries and introduces a continuous timber core, making the apartment brighter and easier to understand.']],
['key'=>'brick-courtyard','slug'=>'brick-courtyard-renovation','type'=>'renovation','image'=>11,'fa'=>['title'=>'بازسازی حیاط آجری','location'=>'قزوین','client'=>'خانه فرهنگ رواق','architect'=>'نیما دادفر','status'=>'تکمیل‌شده','duration'=>'۱۳ ماه','budget'=>'سطح سرمایه‌گذاری متوسط','awards'=>'نامزد برنامه فرضی «Urban Again 2026»','materials'=>'آجر بازیافتی، آهک، چوب توت، فولاد خام','concept'=>'حیاط دوباره به قلب ساختمان تبدیل شد و فضاهای فرهنگی جدید به‌جای پوشاندن ساختار قدیمی، درون آن با فاصله قرار گرفتند.','challenge'=>'مداخلات چند دهه گذشته تناسب حیاط و ورودی اصلی را از بین برده بود.','solution'=>'الحاقات کم‌ارزش حذف و آجرهای سالم برای کف و دیوارهای جدید دوباره استفاده شدند.','timeline'=>'آسیب‌شناسی ۶ هفته • طراحی و مجوز ۱۴ هفته • اجرا ۹ ماه','content'=>'رواق یک خانه تاریخی کوچک را به فضای فرهنگی محله تبدیل می‌کند. پروژه به‌جای بازسازی نمایشی، روی دوام، خوانایی و استفاده روزمره تمرکز دارد.'], 'en'=>['title'=>'Brick Courtyard Renewal','location'=>'Qazvin, Iran','client'=>'Ravaq Cultural House','architect'=>'Nima Dadfar','status'=>'Completed','duration'=>'13 months','budget'=>'Mid investment range','awards'=>'Nominated — Urban Again 2026 (fictional demo recognition)','materials'=>'Reclaimed brick, lime, mulberry wood, raw steel','concept'=>'The courtyard becomes the heart of the building again, while new cultural rooms sit slightly apart from the old structure.','challenge'=>'Decades of additions had erased the original proportions of the courtyard and entrance sequence.','solution'=>'Low-value additions were removed and sound bricks were reused in new floors and walls.','timeline'=>'Condition study 6 weeks • Design & permits 14 weeks • Construction 9 months','content'=>'Ravaq converts a small historic house into a neighborhood cultural venue. Rather than a theatrical restoration, the project prioritizes durability, legibility and everyday use.']]
